insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-grammar','Составьте: Короткая фраза прерывает плавный ритм и обнажает сомнение.','["Krótkie zdanie przełamuje płynny rytm i odsłania wątpliwość.","Płynny rytm ukrywa każde krótkie zdanie.","Wątpliwość rytmem zdanie przełamała."]',0,'Два глагола описывают формальный приём и его смысловую функцию.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-grammar','Составьте: Не отказываясь от иронии, автор смягчает её последней оговоркой.','["Nie rezygnując z ironii, autor łagodzi ją końcowym zastrzeżeniem.","Autor rezygnuje z ironii, więc ją wzmacnia.","Ironia autora zastrzeżenie łagodzić."]',0,'Nie rezygnując сохраняет приём, а łagodzi обозначает изменение интенсивности.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-grammar','Która zmiana świadomie moduluje tempo?','["Seria krótkich zdań przyspiesza scenę po długim opisie.","Każde zdanie ma identyczną długość bez powodu.","Usunięto wszystkie czasowniki."]',0,'Контраст длины предложений связан с динамикой сцены.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-grammar','Gdzie ironia pozostaje dyskretna?','["Bohater «punktualnie» przyszedł tylko godzinę po terminie.","Autor pisze: to jest ironia.","Bohater przyszedł punktualnie."]',0,'Кавычки и контекст создают иронию без прямого комментария.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-grammar','Co grozi manieryzmem?','["Powtarzanie efektownego chwytu niezależnie od funkcji.","Dobór rytmu do sceny.","Korekta niejasnego zaimka."]',0,'Манерность возникает, когда заметный приём становится автоматическим.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-grammar','Która puenta jest celowo wyciszona?','["I może właśnie dlatego nikt więcej o tym nie wspomniał.","OTO JEDYNA PRAWDA!","Wniosek numer jeden brzmi następująco."]',0,'Модальность и спокойный ритм оставляют послевкусие вместо декларации.',5,true);
