insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-reading-check','Dlaczego pierwszy szkic nie miał wyraźnego głosu?','["Każda fraza miała ten sam schemat","Zawierał błędy ortograficzne","Nie miał żadnych przykładów"]',0,'Монотонная композиция не поддерживала желаемый эффект.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-reading-check','Jaką funkcję pełniło «Nagle cisza»?','["Odtwarzało nagłą zmianę doświadczenia","Wyjaśniało termin techniczny","Podsumowywało cały tekst"]',0,'Короткая фраза моделировала событие.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-reading-check','Dlaczego usunięto komentarz do sceny telefonicznej?','["Kontrast sam tworzył komizm","Scena była nieprawdziwa","Humor był zakazany"]',0,'Ирония работала без авторского объяснения.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-reading-check','Co było problemem pierwszej puenty?','["Łamała ton ciekawości oskarżeniem","Była zbyt krótka","Zawierała pytanie"]',0,'Резкая декларация не совпадала с голосом текста.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-reading-check','Czym zastąpiono mocną puentę?','["Pytaniem o znaczenie wspólnej ciszy","Listą zasad","Cytatem z regulaminu"]',0,'Открытый вопрос сохранил наблюдательный тон.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c29-reading-check','Co ostatecznie tworzyło głos Mai?','["Konsekwencja funkcjonalnych wyborów","Liczba figur stylistycznych","Wyłącznie pierwsza osoba"]',0,'Финал определяет голос как систему решений.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c29-tekst','c2-authorial-voice','Авторский голос','Осознанно управляем ритмом, тоном и синтаксисом, сохраняя собственную позицию','C2',16,'🖋️','["Maja pisała felieton o ciszy w pociągach. Pierwsza wersja była poprawna, lecz każda fraza miała ten sam rytm: teza, przykład, komentarz. Tekst brzmiał jak sprawne sprawozdanie, choć autorka chciała połączyć obserwację z dyskretnym humorem.","W drugim szkicu zaczęła od długiego zdania o rozmowach, stukocie kół i sygnałach telefonów. Potem postawiła dwa słowa: «Nagle cisza». Krótka fraza nie była ozdobą; odtwarzała zmianę, której doświadczyli pasażerowie po wjeździe do tunelu.","Maja usunęła trzy dowcipy, które tłumaczyły własną ironię. Zostawiła scenę z panem ogłaszającym przez telefon, że właśnie korzysta ze strefy ciszy. Komizm wynikał z kontrastu między deklaracją a zachowaniem, więc komentarz autorki stał się zbędny.","Redaktorka zwróciła uwagę na zakończenie. Mocna puenta oskarżała wszystkich podróżnych o egoizm i łamała wcześniejszy ton ciekawości. Maja zastąpiła ją pytaniem, czy cisza jest jeszcze wspólną przestrzenią, czy już usługą zamawianą przez słuchawki.","Felieton nie stał się bardziej «literacki» przez nagromadzenie figur. Stał się bardziej jej: uważny, lekko ironiczny i rytmicznie zmienny. Autorstwo ujawniło się w konsekwencji wyborów oraz w gotowości do usunięcia efektu, który nie służył perspektywie tekstu."]','{"głos autorski":{"lemma":"głos autorski","translation":"авторский голос","part_of_speech":"wyrażenie rzeczownikowe"},"ton wypowiedzi":{"lemma":"ton wypowiedzi","translation":"тон высказывания","part_of_speech":"wyrażenie rzeczownikowe"},"rytm prozy":{"lemma":"rytm prozy","translation":"ритм прозы","part_of_speech":"wyrażenie rzeczownikowe"},"kadencja zdania":{"lemma":"kadencja zdania","translation":"каденция предложения","part_of_speech":"wyrażenie rzeczownikowe"},"fraza rozpoznawalna":{"lemma":"fraza rozpoznawalna","translation":"узнаваемая фраза","part_of_speech":"wyrażenie rzeczownikowe"},"dystans narracyjny":{"lemma":"dystans narracyjny","translation":"нарративная дистанция","part_of_speech":"wyrażenie rzeczownikowe"},"ironia dyskretna":{"lemma":"ironia dyskretna","translation":"тонкая ирония","part_of_speech":"wyrażenie rzeczownikowe"},"zagęszczenie składni":{"lemma":"zagęszczenie składni","translation":"синтаксическое уплотнение","part_of_speech":"wyrażenie rzeczownikowe"},"modulować tempo":{"lemma":"modulować tempo","translation":"модулировать темп","part_of_speech":"wyrażenie czasownikowe"},"przełamać regularność":{"lemma":"przełamać regularność","translation":"нарушить регулярность","part_of_speech":"wyrażenie czasownikowe"},"wyciszyć puentę":{"lemma":"wyciszyć puentę","translation":"приглушить финальный акцент","part_of_speech":"wyrażenie czasownikowe"},"wyostrzyć kontrast":{"lemma":"wyostrzyć kontrast","translation":"обострить контраст","part_of_speech":"wyrażenie czasownikowe"},"unikać manieryzmu":{"lemma":"unikać manieryzmu","translation":"избегать манерности","part_of_speech":"wyrażenie czasownikowe"},"zachować idiomatyczność":{"lemma":"zachować idiomatyczność","translation":"сохранить идиоматичность","part_of_speech":"wyrażenie czasownikowe"},"pisać we własnym rejestrze":{"lemma":"pisać we własnym rejestrze","translation":"писать в собственном регистре","part_of_speech":"fraza"},"pauza retoryczna":{"lemma":"pauza retoryczna","translation":"риторическая пауза","part_of_speech":"wyrażenie rzeczownikowe"},"perspektywa pierwszoosobowa":{"lemma":"perspektywa pierwszoosobowa","translation":"перспектива первого лица","part_of_speech":"wyrażenie rzeczownikowe"},"spójność tonalna":{"lemma":"spójność tonalna","translation":"тональная связность","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c29-reading-check"}',65,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
