insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c210-grammar','c2-capstone-project','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Создаём и защищаем сложный многожанровый проект с прозрачной самооценкой',14,'🏁','Проект C2','[["Единый замысел, разные жанры","Проект объединяет аналитический текст, адаптацию для другой аудитории и устную защиту. Зафиксируй инварианты содержания, источники, риски и критерии до начала редактирования."],["Самооценка по доказательствам","Не оценивай работу общими словами. Покажи конкретную правку, объясни её эффект, назови оставшееся ограничение и следующий шаг. Итоговый уровень остаётся учебной целью, а не официальной сертификацией."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',338,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
