insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c210-grammar','Составьте: В итоговой версии я сузил вывод, поскольку один источник не подтверждал причинность.','["W wersji finalnej zawęziłem wniosek, ponieważ jedno źródło nie potwierdzało przyczynowości.","Jedno źródło dowodziło wszystkiego, dlatego rozszerzyłem wniosek.","Wniosek finalny źródłem przyczynowość."]',0,'Ponieważ связывает редакторское решение с доказательным основанием.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c210-grammar','Составьте: Я сохранила метафору, но изменила абзац так, чтобы яснее показать ограничение.','["Zachowałam metaforę, lecz przebudowałam akapit tak, aby wyraźniej pokazać ograniczenie.","Usunęłam ograniczenie, żeby metafora była pewna.","Metafora akapit ograniczeniem zachowała."]',0,'Lecz сохраняет контраст, tak aby вводит функцию правки.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c210-grammar','Które kryterium sukcesu jest sprawdzalne?','["Odbiorca odróżnia fakt, interpretację i rekomendację.","Tekst robi dobre wrażenie.","Projekt jest bardzo ciekawy."]',0,'Критерий описывает наблюдаемое понимание аудитории.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c210-grammar','Jak obronić zmianę gatunku?','["Wskazać potrzeby odbiorcy, zachowane inwarianty i koszt kompresji.","Powiedzieć, że krócej zawsze znaczy lepiej.","Pominąć źródła."]',0,'Защита связывает форму с аудиторией и смысловыми рисками.',3,true);
