insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c210-tekst','c2-capstone-project','Проект C2','Создаём и защищаем сложный многожанровый проект с прозрачной самооценкой','C2',16,'🏁','["Kamil przygotował projekt o zielonych dachach. Miał stworzyć analizę dla rady miasta, krótką informację dla mieszkańców i pięciominutową obronę decyzji redakcyjnych. W briefie zapisał wspólny cel: wyjaśnić możliwe korzyści bez obiecywania efektów, których lokalne dane jeszcze nie potwierdzają.","Analiza porównywała trzy źródła: eksperyment z innym klimatem, miejskie dane obserwacyjne i wywiady z administratorami budynków. Kamil oddzielił wyniki dotyczące temperatury od opinii o kosztach. Wniosek zawęził do pilotażu, ponieważ żaden materiał nie rozstrzygał długoterminowej opłacalności.","W wersji dla mieszkańców zrezygnował z tabeli, lecz zachował dwie liczby i główne zastrzeżenie. Termin «retencja» wyjaśnił przykładem wody zatrzymanej po ulewie. Nie użył hasła «dachy chłodzą miasto», tylko napisał, że mogą ograniczać nagrzewanie wybranych budynków.","Podczas obrony recenzentka zapytała, dlaczego opis pilotażu pojawia się przed najbardziej efektownym przykładem zagranicznym. Kamil wyjaśnił, że odbiorca najpierw powinien poznać realny zakres decyzji. Po informacji zwrotnej dodał jednak krótkie zdanie łączące przykład z lokalnym pytaniem.","W arkuszu samooceny wskazał mocną hierarchię dowodów i precyzyjną adaptację terminu. Za słabość uznał brak perspektywy osób wynajmujących mieszkania. Projekt zamknął planem kolejnego wywiadu, a nie deklaracją doskonałości. Finalna wersja dokumentowała zarówno rezultat, jak i drogę jego rewizji."]','{"projekt wielogatunkowy":{"lemma":"projekt wielogatunkowy","translation":"многожанровый проект","part_of_speech":"wyrażenie rzeczownikowe"},"brief komunikacyjny":{"lemma":"brief komunikacyjny","translation":"коммуникационный бриф","part_of_speech":"wyrażenie rzeczownikowe"},"kryterium sukcesu":{"lemma":"kryterium sukcesu","translation":"критерий успеха","part_of_speech":"wyrażenie rzeczownikowe"},"łańcuch argumentacji":{"lemma":"łańcuch argumentacji","translation":"цепочка аргументации","part_of_speech":"wyrażenie rzeczownikowe"},"wersja dla odbiorcy":{"lemma":"wersja dla odbiorcy","translation":"версия для аудитории","part_of_speech":"wyrażenie rzeczownikowe"},"nota metodologiczna":{"lemma":"nota metodologiczna","translation":"методологическая записка","part_of_speech":"wyrażenie rzeczownikowe"},"arkusz samooceny":{"lemma":"arkusz samooceny","translation":"лист самооценки","part_of_speech":"wyrażenie rzeczownikowe"},"informacja zwrotna":{"lemma":"informacja zwrotna","translation":"обратная связь","part_of_speech":"wyrażenie rzeczownikowe"},"zdefiniować zakres":{"lemma":"zdefiniować zakres","translation":"определить объём","part_of_speech":"wyrażenie czasownikowe"},"uzasadnić wybór gatunku":{"lemma":"uzasadnić wybór gatunku","translation":"обосновать выбор жанра","part_of_speech":"wyrażenie czasownikowe"},"udokumentować źródło":{"lemma":"udokumentować źródło","translation":"задокументировать источник","part_of_speech":"wyrażenie czasownikowe"},"skalibrować wniosek":{"lemma":"skalibrować wniosek","translation":"калибровать вывод","part_of_speech":"wyrażenie czasownikowe"},"obronić decyzję redakcyjną":{"lemma":"obronić decyzję redakcyjną","translation":"защитить редакторское решение","part_of_speech":"wyrażenie czasownikowe"},"zrewidować szkic":{"lemma":"zrewidować szkic","translation":"переработать черновик","part_of_speech":"wyrażenie czasownikowe"},"wyciągnąć wnioski z procesu":{"lemma":"wyciągnąć wnioski z procesu","translation":"сделать выводы из процесса","part_of_speech":"fraza"},"portfolio":{"lemma":"portfolio","translation":"портфолио","part_of_speech":"rzeczownik"},"wersja finalna":{"lemma":"wersja finalna","translation":"финальная версия","part_of_speech":"wyrażenie rzeczownikowe"},"ślad zmian":{"lemma":"ślad zmian","translation":"история изменений","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c210-reading-check"}',66,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
